<?php defined('ABSPATH')||exit; function bluprint_shop_archive_defaults(){ return ['title'=>'ابزار ایده‌های تو','description'=>'مجموعه‌ای از بهترین ابزارها و متریال‌های هنری و معماری، برای ساختن، طراحی کردن و بهتر دیدن جهان.','image_left'=>0,'image_right'=>0,'content'=>'']; } function bluprint_shop_archive_settings(){ return wp_parse_args(get_option('bluprint_shop_archive',[]),bluprint_shop_archive_defaults()); } function bluprint_shop_archive_sanitize($v){ $d=bluprint_shop_archive_defaults(); $v=is_array($v)?$v:[]; return [ 'title'=>sanitize_text_field($v['title']??$d['title']), 'description'=>sanitize_textarea_field($v['description']??$d['description']), 'image_left'=>absint($v['image_left']??0), 'image_right'=>absint($v['image_right']??0), 'content'=>wp_kses_post($v['content']??'') ]; } function bluprint_shop_archive_admin(){ if(!current_user_can('manage_woocommerce'))return; $d=bluprint_shop_archive_settings(); ?> <div class="wrap"> <h1>تنظیمات آرشیو فروشگاه</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_shop_archive_group');?> <table class="form-table"> <tr> <th><label for="bp-archive-title">عنوان آرشیو</label></th> <td><input class="regular-text" id="bp-archive-title" name="bluprint_shop_archive[title]" value="<?php echo esc_attr($d['title']);?>"></td> </tr> <tr> <th><label for="bp-archive-description">توضیحات کوتاه</label></th> <td><textarea class="large-text" rows="3" id="bp-archive-description" name="bluprint_shop_archive[description]"><?php echo esc_textarea($d['description']);?></textarea></td> </tr> <tr> <th>تصویر سمت چپ</th> <td> <?php echo wp_get_attachment_image($d['image_left'],'thumbnail',['class'=>'bp-admin-preview']);?> <input type="hidden" name="bluprint_shop_archive[image_left]" value="<?php echo esc_attr($d['image_left']);?>"> <button type="button" class="button bp-archive-image" data-target="image_left">انتخاب تصویر</button> <button type="button" class="button bp-archive-remove" data-target="image_left">حذف</button> </td> </tr> <tr> <th>تصویر سمت راست</th> <td> <?php echo wp_get_attachment_image($d['image_right'],'thumbnail',['class'=>'bp-admin-preview']);?> <input type="hidden" name="bluprint_shop_archive[image_right]" value="<?php echo esc_attr($d['image_right']);?>"> <button type="button" class="button bp-archive-image" data-target="image_right">انتخاب تصویر</button> <button type="button" class="button bp-archive-remove" data-target="image_right">حذف</button> </td> </tr> <tr> <th><label for="bp-archive-content">محتوای انتهای آرشیو</label></th> <td><?php wp_editor($d['content'],'bp_shop_archive_content',['textarea_name'=>'bluprint_shop_archive[content]','textarea_rows'=>8]);?></td> </tr> </table> <?php submit_button();?> </form> </div> <?php } function bluprint_shop_archive_admin_assets($hook){ if(!bluprint_is_admin_page('bluprint-shop-archive'))return; wp_enqueue_media(); wp_add_inline_script('jquery-core',"(function($){let frame;$(document).on('click','.bp-archive-image',function(e){e.preventDefault();const b=$(this),field=b.data('target'),input=b.siblings('input[type=hidden]'),preview=b.siblings('.bp-admin-preview');frame=wp.media({title:'انتخاب تصویر',button:{text:'استفاده از تصویر'},multiple:false});frame.on('select',function(){const a=frame.state().get('selection').first().toJSON();input.val(a.id);if(preview.length)preview.attr('src',a.sizes?.thumbnail?.url||a.url);else b.before('<img class=\"bp-admin-preview\" src=\"'+(a.sizes?.thumbnail?.url||a.url)+'\" style=\"max-width:100px;display:block;margin-bottom:8px\">')});frame.open()}).on('click','.bp-archive-remove',function(){const b=$(this);b.siblings('input[type=hidden]').val('');b.siblings('.bp-admin-preview').remove()})})(jQuery);"); } add_action('admin_enqueue_scripts','bluprint_shop_archive_admin_assets'); function bluprint_shop_archive_register(){ register_setting('bluprint_shop_archive_group','bluprint_shop_archive',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_shop_archive_sanitize', 'default'=>bluprint_shop_archive_defaults() ]); add_submenu_page('bluprint-settings','تنظیمات آرشیو فروشگاه','آرشیو فروشگاه','manage_woocommerce','bluprint-shop-archive','bluprint_shop_archive_admin'); } add_action('admin_menu','bluprint_shop_archive_register'); function bluprint_archive_filter_args(){ $decimal=static function($key){ if(!isset($_GET[$key])||is_array($_GET[$key]))return ''; $value=wc_format_decimal(wp_unslash($_GET[$key])); return $value!==''&&is_numeric($value)?(string)max(0,(float)$value):''; }; $ids=static function($key){ if(!isset($_GET[$key]))return []; $values=(array)wp_unslash($_GET[$key]); return array_values(array_unique(array_filter(array_map('absint',$values)))); }; return [ 'min'=>$decimal('min_price'), 'max'=>$decimal('max_price'), 'cats'=>$ids('filter_category'), 'brands'=>$ids('filter_brand'), 'stock'=>isset($_GET['stock_status'])&&sanitize_key(wp_unslash($_GET['stock_status']))==='instock' ]; } function bluprint_archive_price_bounds(){ global $wpdb; $table=$wpdb->prefix.'wc_product_meta_lookup'; $row=$wpdb->get_row("SELECT MIN(min_price) AS min_price,MAX(max_price) AS max_price FROM {$table}",ARRAY_A); $min=isset($row['min_price'])?(float)$row['min_price']:0; $max=isset($row['max_price'])?(float)$row['max_price']:1000000; if($max<=$min)$max=$min+1000; return ['min'=>$min,'max'=>$max,'step'=>($max-$min)>=1000?1000:1]; } function bluprint_archive_filter_query($q){ if(!$q instanceof WP_Query||!$q->is_main_query())return; $is_product_archive=$q->is_post_type_archive('product') ||$q->is_tax('product_cat') ||$q->is_tax('product_tag') ||$q->is_tax('product_brand'); if(!$is_product_archive)return; $f=bluprint_archive_filter_args(); $tax_parts=[]; $existing_tax=(array)$q->get('tax_query'); if($existing_tax)$tax_parts[]=$existing_tax; if($f['cats']){ $tax_parts[]=[ 'taxonomy'=>'product_cat', 'field'=>'term_id', 'terms'=>$f['cats'], 'operator'=>'IN', 'include_children'=>true ]; } if($f['brands']&&taxonomy_exists('product_brand')){ $tax_parts[]=[ 'taxonomy'=>'product_brand', 'field'=>'term_id', 'terms'=>$f['brands'], 'operator'=>'IN' ]; } if($tax_parts){ $tax_query=['relation'=>'AND']; foreach($tax_parts as $part)$tax_query[]=$part; $q->set('tax_query',$tax_query); } $meta_parts=[]; $existing_meta=(array)$q->get('meta_query'); if($existing_meta)$meta_parts[]=$existing_meta; if($f['min']!==''&&$f['max']!==''){ $meta_parts[]=[ 'key'=>'_price', 'value'=>[(float)$f['min'],(float)$f['max']], 'compare'=>'BETWEEN', 'type'=>'DECIMAL' ]; }elseif($f['min']!==''){ $meta_parts[]=[ 'key'=>'_price', 'value'=>(float)$f['min'], 'compare'=>'>=', 'type'=>'DECIMAL' ]; }elseif($f['max']!==''){ $meta_parts[]=[ 'key'=>'_price', 'value'=>(float)$f['max'], 'compare'=>'<=', 'type'=>'DECIMAL' ]; } if($f['stock']){ $meta_parts[]=[ 'key'=>'_stock_status', 'value'=>'instock', 'compare'=>'=' ]; } if($meta_parts){ $meta_query=['relation'=>'AND']; foreach($meta_parts as $part)$meta_query[]=$part; $q->set('meta_query',$meta_query); } $q->set('posts_per_page',24); } add_action('woocommerce_product_query','bluprint_archive_filter_query',99,1); function bluprint_archive_base_url(){ if(is_shop()){ $url=get_permalink(wc_get_page_id('shop')); return $url?:home_url('/shop/'); } $term=get_queried_object(); if($term instanceof WP_Term){ $url=get_term_link($term); if(!is_wp_error($url))return $url; } return wc_get_page_permalink('shop'); } function bluprint_archive_url($args=[]){ $keys=['min_price','max_price','filter_category','filter_brand','stock_status','orderby','product-page']; $url=remove_query_arg($keys); $current=wp_unslash($_GET); foreach(['min_price','max_price','filter_category','filter_brand','stock_status','orderby'] as $key){ if(isset($current[$key])&&!array_key_exists($key,$args))$args[$key]=$current[$key]; } foreach($args as $key=>$value){ if($value===''||$value===[]||$value===null)$url=remove_query_arg($key,$url); else $url=add_query_arg($key,$value,$url); } return esc_url($url); } function bluprint_archive_filter_terms($taxonomy){ if(!taxonomy_exists($taxonomy))return []; return bluprint_get_ordered_terms($taxonomy,[ 'hide_empty'=>true, 'orderby'=>'name', 'order'=>'ASC' ]); } function bluprint_archive_canonical($canonical){ if(is_shop()){ $url=get_permalink(wc_get_page_id('shop')); return $url?:$canonical; } if(is_product_taxonomy()){ $term=get_queried_object(); if($term instanceof WP_Term){ $url=get_term_link($term); if(!is_wp_error($url))return $url; } } return $canonical; } add_filter('get_canonical_url','bluprint_archive_canonical',99); add_filter('rank_math/frontend/canonical','bluprint_archive_canonical',99); function bluprint_archive_noindex_filtered($robots){ if(!is_array($robots))return $robots; $keys=['min_price','max_price','filter_category','filter_brand','stock_status','orderby']; foreach($keys as $key){ if(isset($_GET[$key])&&$_GET[$key]!==''&&$_GET[$key]!==[]){ $robots['index']='noindex'; break; } } return $robots; } add_filter('rank_math/frontend/robots','bluprint_archive_noindex_filtered',99);